t.script:
document.addEventListener('DOMContentLoaded', function() {
    // Configuration AJAX
    const uploadUrl = '';
    const progressUrl = '';
    const csrfToken = '';

    // Gestion des uploads de fichiers
    document.querySelectorAll('input[type="file"]').forEach(input => {
        const docType = input.closest('.upload-zone').getAttribute('data-doctype');
        const fileSelectedDiv = document.getElementById('file-selected-' + docType);
        const progressDiv = document.getElementById('progress-' + docType);

        input.addEventListener('change', function(e) {
            const file = e.target.files[0];
            if (file) {
                // Afficher le fichier sélectionné
                if (fileSelectedDiv) {
                    fileSelectedDiv.querySelector('.filename').textContent = file.name;
                    fileSelectedDiv.style.display = 'flex';
                }

                // Marquer la card comme uploadée
                const card = input.closest('.document-card');
                if (card) {
                    card.classList.add('uploaded');
                }
            }
        });
    });

    // Gestion du drag & drop
    document.querySelectorAll('.upload-zone').forEach(zone => {
        ['dragover', 'dragenter'].forEach(eventName => {
            zone.addEventListener(eventName, e => {
                e.preventDefault();
                e.stopPropagation();
                zone.classList.add('dragover');
            });
        });

        ['dragleave', 'dragend', 'drop'].forEach(eventName => {
            zone.addEventListener(eventName, e => {
                e.preventDefault();
                e.stopPropagation();
                zone.classList.remove('dragover');
            });
        });

        zone.addEventListener('drop', e => {
            const files = e.dataTransfer.files;
            if (files.length > 0) {
                const input = zone.querySelector('input[type="file"]');
                input.files = files;
                input.dispatchEvent(new Event('change'));
            }
        });
    });

    // Gestion de la soumission du formulaire
    const form = document.getElementById('documentUploadForm');
    const submitBtn = document.getElementById('submitBtn');

    form.addEventListener('submit', function(e) {
        // Désactiver le bouton et afficher le loading
        submitBtn.innerHTML = 'Envoi en cours...';
        submitBtn.disabled = true;

        // Afficher la progression
        document.querySelectorAll('.progress-modern').forEach(progress => {
            progress.style.display = 'block';
            const bar = progress.querySelector('.progress-bar-modern');
            let width = 0;
            const interval = setInterval(() => {
                width += Math.random() * 15;
                if (width >= 90) {
                    clearInterval(interval);
                    width = 90;
                }
                bar.style.width = width + '%';
            }, 200);
        });
    });

    // Fonction pour télécharger un document
    window.downloadDocument = function(docId) {
        const downloadUrl = '/documents/upload//download/' + docId;
        window.open(downloadUrl, '_blank');
    };

    // Auto-refresh du statut (optionnel)
    if (progressUrl) {
        setInterval(() => {
            fetch(progressUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-CSRFToken': csrfToken
                }
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    // Mettre à jour les statistiques si nécessaire
                    console.log('Progress update:', data.data);
                }
            })
            .catch(error => console.log('Progress check failed:', error));
        }, 30000); // Toutes les 30 secondes
    }
});
